// Prijíma iba správy z vlastníkovho chatu. Cudzie správy sa ticho zahodia (bot nič neprezradí).
const OWNER_CHAT_ID = 'REPLACE_WITH_OWNER_TELEGRAM_CHAT_ID';
const MAX_DOWNLOAD = 20 * 1024 * 1024; // limit Telegram Bot API na stiahnutie
const out = [];
for (const item of $input.all()) {
  const m = item.json.message || {};
  const chatId = String(m.chat?.id ?? '');
  if (!chatId || chatId !== OWNER_CHAT_ID || !m.message_id) continue;
  const text = String(m.text || '');
  const caption = String(m.caption || '');
  const entities = [...(m.entities || []), ...(m.caption_entities || [])];
  const linkEntities = entities.filter(e => e.type === 'text_link' && e.url).map(e => e.url);
  const inline = ((text + ' ' + caption).match(/https?:\/\/[^\s<>"')\]]+/gi) || []).map(u => u.replace(/[.,;:!?]+$/, ''));
  const urls = [...new Set([...linkEntities, ...inline])].slice(0, 10);
  let fileId = '', mimeType = '', fileName = '', fileSize = 0, kind = urls.length ? 'link' : 'text';
  if (m.voice) { fileId = m.voice.file_id; mimeType = m.voice.mime_type || 'audio/ogg'; fileName = 'hlasovka-' + m.message_id + '.ogg'; fileSize = m.voice.file_size || 0; kind = 'voice'; }
  else if (m.audio) { fileId = m.audio.file_id; mimeType = m.audio.mime_type || 'audio/mpeg'; fileName = m.audio.file_name || ('audio-' + m.message_id); fileSize = m.audio.file_size || 0; kind = 'voice'; }
  else if (m.photo?.length) { const p = m.photo[m.photo.length - 1]; fileId = p.file_id; mimeType = 'image/jpeg'; fileName = 'foto-' + m.message_id + '.jpg'; fileSize = p.file_size || 0; kind = 'image'; }
  else if (m.document) {
    fileId = m.document.file_id; mimeType = String(m.document.mime_type || 'application/octet-stream').toLowerCase();
    fileName = m.document.file_name || ('dokument-' + m.message_id); fileSize = m.document.file_size || 0;
    kind = mimeType.startsWith('image/') ? 'image' : mimeType.startsWith('audio/') ? 'voice' : 'document';
  }
  else if (m.video || m.video_note) { kind = 'video'; mimeType = m.video?.mime_type || 'video/mp4'; fileName = m.video?.file_name || ''; }
  const fileTooBig = fileSize > MAX_DOWNLOAD;
  const origin = m.forward_origin || {};
  const forwardedFrom = origin.sender_user?.first_name || origin.sender_user_name || origin.chat?.title || m.forward_from_chat?.title || '';
  out.push({ json: {
    sourceKey: 'telegram:' + chatId + ':' + m.message_id,
    source: 'telegram', chatId, messageId: m.message_id, kind,
    receivedAt: Number(m.date || Math.floor(Date.now() / 1000)),
    rawText: text, caption, urls, forwardedFrom,
    telegramFileId: fileId, downloadFileId: fileTooBig ? '' : fileId,
    mimeType, fileName, fileTooBig,
  } });
}
return out;

// Spojí správu s kontextom profilu z Convex. Bez profilu analýza beží ďalej, iba menej osobne.
const message = $('Over vlastníka a rozpoznaj obsah').first().json;
const ctx = $input.first().json || {};
const ok = ctx.ok === true && typeof ctx.promptContext === 'string';
return [{ json: { ...message, context: ok ? ctx : { promptContext: 'Profil nie je dostupný.', recent: [] }, contextError: ok ? '' : 'Profil z Convex sa nepodarilo načítať' } }];

// Zostaví vstup pre AI: text + prepis hlasovky + text webu + obrázok/PDF priamo ako multimodálny vstup.
const base = $('Spoj správu a profil').first().json;
const item = $input.first();
const j = item.json || {};
const clean = (s, max) => String(s || '').replace(/\u0000/g, '').trim().slice(0, max);
const stripHtml = html => String(html || '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ').replace(/<!--[\s\S]*?-->/g, ' ')
  .replace(/<(br|p|div|li|h[1-6]|tr)[^>]*>/gi, '\n').replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
const meta = html => {
  const pick = re => (String(html || '').match(re) || [])[1] || '';
  return [pick(/<title[^>]*>([^<]{1,300})<\/title>/i), pick(/<meta[^>]+(?:name|property)=["'](?:og:)?description["'][^>]+content=["']([^"']{1,600})/i)].filter(Boolean).join(' — ');
};

let transcript = '', pageText = '', pageMeta = '', extractedText = '', driveFileId = '', driveUrl = '';
const notes = [];
if (base.contextError) notes.push(base.contextError);
if (base.fileTooBig) notes.push('Súbor je väčší ako 20 MB, Telegram ho nedovolí stiahnuť – analyzuje sa iba popis.');
if (base.kind === 'video') notes.push('Video sa neanalyzuje, použije sa iba popis a odkazy.');
if (base.kind === 'voice' && base.downloadFileId) {
  transcript = clean(j.text, 15000);
  if (!transcript) notes.push('Prepis hlasovky zlyhal.');
}
if (typeof j.pageHtml === 'string') {
  pageMeta = clean(meta(j.pageHtml), 900);
  pageText = clean(stripHtml(j.pageHtml), 15000);
  if (pageText.length < 200) notes.push('Webová stránka vrátila málo textu (možno vyžaduje JavaScript alebo prihlásenie).');
} else if (base.kind === 'link' && !base.downloadFileId) {
  notes.push('Webovú stránku sa nepodarilo stiahnuť.');
}
try {
  const archived = $('Spoj súbor a archív').first().json || {};
  if (archived.id && !archived.error) { driveFileId = String(archived.id); driveUrl = 'https://drive.google.com/file/d/' + driveFileId + '/view'; }
  else if (base.downloadFileId) notes.push('Originál sa nepodarilo uložiť do Drive.');
} catch { /* súbor nebol v správe */ }

const content = [];
const mime = String(base.mimeType || '').toLowerCase();
const binary = item.binary?.data;
if (base.downloadFileId && base.kind !== 'voice' && !binary) notes.push('Súbor sa nepodarilo stiahnuť z Telegramu.');
if (binary && base.kind !== 'voice') {
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  if (mime.startsWith('image/')) content.push({ type: 'input_image', image_url: 'data:' + mime + ';base64,' + buffer.toString('base64'), detail: 'high' });
  else if (mime === 'application/pdf') content.push({ type: 'input_file', filename: base.fileName || 'dokument.pdf', file_data: 'data:application/pdf;base64,' + buffer.toString('base64') });
  else if (/^text\/|json|csv|markdown|xml/.test(mime)) extractedText = clean(buffer.toString('utf8'), 20000);
  else notes.push('Formát ' + (mime || 'neznámy') + ' sa automaticky nečíta – analyzuje sa popis. Tip: pošli PDF alebo screenshot.');
}

const parts = [
  'Typ záznamu: ' + base.kind,
  base.forwardedFrom ? 'Preposlané od: ' + base.forwardedFrom : '',
  base.rawText ? 'Moja správa:\n' + clean(base.rawText, 4000) : '',
  base.caption ? 'Popis k súboru:\n' + clean(base.caption, 2000) : '',
  base.urls.length ? 'Odkazy: ' + base.urls.join(' ') : '',
  base.fileName ? 'Súbor: ' + base.fileName : '',
  transcript ? 'Prepis hlasovej správy:\n' + transcript : '',
  pageMeta ? 'Web – názov a popis: ' + pageMeta : '',
  pageText ? 'Text webovej stránky (skrátený):\n' + pageText : '',
  extractedText ? 'Text dokumentu:\n' + extractedText : '',
  notes.length ? 'Technické poznámky: ' + notes.join(' ') : '',
].filter(Boolean);
content.unshift({ type: 'input_text', text: parts.join('\n\n') });

const instructions = [
  'Si môj osobný knowledge kurátor a sparring partner. Posielam ti veci, ktoré ma zaujali. Tvoja úloha je upratať ich a vytiahnuť z nich to, čo je pre MŇA užitočné.',
  'Píš po slovensky, stručne a konkrétne. Žiadne všeobecné frázy.',
  '- title: výstižný názov do 80 znakov (nie názov webu, ale o čom to je).',
  '- summary: 2–4 vety, čo to je a prečo je to zaujímavé.',
  '- keyPoints: max 7 konkrétnych poznatkov / know-how, ktoré si mám zapamätať.',
  '- frameworks: iba ak obsah obsahuje alebo prirodzene ponúka použiteľný postup/model. Pomenuj ho, kedy ho použiť a kroky. Inak prázdne pole.',
  '- businessIdeas: max 3 biznis nápady, ktoré z toho vyplývajú PRE MŇA – nadväzuj na moje oblasti a projekty. Ak nič zmysluplné, prázdne pole.',
  '- relevanceScore 0–100: ako veľmi to súvisí s mojimi oblasťami, projektmi, cieľmi a otázkami. 80+ = priamo použiteľné teraz, 50–79 = súvisí, pod 30 = mimo mojich tém. Témy z „Čo ma nezaujíma“ hodnoť nízko.',
  '- relevanceWhy: jedna veta, na čo konkrétne z môjho profilu to nadväzuje. linkedFocus: presné názvy oblastí/projektov z profilu.',
  '- nextActions: max 3 konkrétne kroky (napr. „Otestovať X na projekte Y“). Prázdne, ak nedáva zmysel.',
  '- tags: 3–6 krátkych tagov malými písmenami, opakuj existujúce tagy z mojich tém, ak sedia.',
  '- relatedCaptureIds: ID nedávnych záznamov, ktoré s týmto naozaj súvisia. Používaj IBA ID zo zoznamu nižšie.',
  '- profileSignals: max 2 nové záujmy, ktoré v mojom profile chýbajú, ale z tohto a mojich opakovaných tém vyplývajú. Väčšinou prázdne.',
  '- category: Know-how | Framework | Biznis nápad | Nástroj | Inšpirácia | Referencia | Úloha (Úloha = je to pripomienka niečo urobiť).',
  'Ak sa obsah nepodarilo prečítať, napíš to v summary, nevymýšľaj si obsah a daj relevanceScore podľa toho, čo vieš.',
  '',
  'MÔJ PROFIL A KONTEXT:',
  base.context.promptContext,
].join('\n');

const str = { type: 'string' };
const arr = items => ({ type: 'array', items });
const obj = props => ({ type: 'object', additionalProperties: false, required: Object.keys(props), properties: props });
const schema = obj({
  title: str, summary: str,
  category: { type: 'string', enum: ['Know-how', 'Framework', 'Biznis nápad', 'Nástroj', 'Inšpirácia', 'Referencia', 'Úloha'] },
  keyPoints: arr(str),
  frameworks: arr(obj({ name: str, whenToUse: str, steps: arr(str) })),
  businessIdeas: arr(obj({ title: str, problem: str, audience: str, firstStep: str })),
  relevanceScore: { type: 'integer', minimum: 0, maximum: 100 },
  relevanceWhy: str, linkedFocus: arr(str), nextActions: arr(str), tags: arr(str),
  relatedCaptureIds: arr(str), profileSignals: arr(str),
});

const capture = {
  sourceKey: base.sourceKey, source: 'telegram', kind: base.kind, receivedAt: base.receivedAt,
  rawText: base.rawText, caption: base.caption, urls: base.urls, fileName: base.fileName, mimeType: base.mimeType,
  telegramFileId: base.telegramFileId, driveFileId, driveUrl,
  extractedText: [transcript && ('Prepis: ' + transcript), pageText && ('Web: ' + pageText), extractedText].filter(Boolean).join('\n\n').slice(0, 20000),
};

return [{ json: {
  chatId: base.chatId, messageId: base.messageId, notes, capture,
  requestBody: {
    model: 'gpt-5-mini',
    instructions,
    input: [{ role: 'user', content }],
    reasoning: { effort: 'low' },
    max_output_tokens: 6000,
    text: { format: { type: 'json_schema', name: 'idea_capture', strict: true, schema } },
  },
} }];

// Rozparsuje AI výstup. Pri chybe sa záznam uloží aj tak – surový, s chybou na neskoršie spracovanie.
const prepared = $('Priprav AI analýzu').first().json;
const j = $input.first().json || {};
let text = j.output_text || '';
if (!text && Array.isArray(j.output)) text = j.output.flatMap(x => x.content || []).filter(x => x.type === 'output_text').map(x => x.text || '').join('');
let enrichment = null, analysisError = '';
if (j.error) analysisError = 'OpenAI: ' + String(j.error.message || j.error).slice(0, 200);
else if (j.status === 'incomplete') analysisError = 'OpenAI odpoveď je neúplná: ' + String(j.incomplete_details?.reason || '');
else {
  try { enrichment = JSON.parse(text); if (!enrichment || typeof enrichment !== 'object' || Array.isArray(enrichment)) throw new Error('bad'); }
  catch { enrichment = null; analysisError = 'AI nevrátila platný JSON'; }
}
const notes = prepared.notes || [];
if (!analysisError && notes.length) analysisError = notes.join(' ').slice(0, 300);
return [{ json: { chatId: prepared.chatId, messageId: prepared.messageId, payload: { ...prepared.capture, enrichment, analysisError } } }];

// Krátke potvrdenie späť do Telegramu.
const built = $('Zostav záznam pre Convex').first().json;
const saved = $input.first().json || {};
const e = built.payload.enrichment || {};
const lines = [];
if (saved.ok !== true) {
  lines.push('⚠️ Záznam sa nepodarilo uložiť do trezora. Skús ho poslať znova o pár minút.');
  if (saved.errors) lines.push(String(saved.errors).slice(0, 300));
} else if (!e.title) {
  lines.push('📥 Uložené bez AI analýzy: ' + (saved.title || 'záznam'));
  if (built.payload.analysisError) lines.push(built.payload.analysisError);
} else {
  lines.push((saved.duplicate ? '🔁 Aktualizované: ' : '💡 Uložené: ') + e.title);
  lines.push(e.category + ' · relevancia ' + e.relevanceScore + '/100' + (e.tags?.length ? ' · #' + e.tags.slice(0, 4).join(' #') : ''));
  if (e.relevanceWhy) lines.push('🎯 ' + e.relevanceWhy);
  if (e.keyPoints?.length) lines.push('', ...e.keyPoints.slice(0, 3).map(p => '• ' + p));
  if (e.frameworks?.length) lines.push('', '🧩 Framework: ' + e.frameworks.map(f => f.name).join(', '));
  if (e.businessIdeas?.length) lines.push('🚀 Biznis nápad: ' + e.businessIdeas.map(b => b.title).join(' | '));
  if (e.nextActions?.length) lines.push('➡️ ' + e.nextActions[0]);
  if (e.relatedCaptureIds?.length) lines.push('🔗 Súvisí s ' + e.relatedCaptureIds.length + ' staršími záznamami.');
  if (e.profileSignals?.length) lines.push('✨ Nový záujem do profilu? ' + e.profileSignals.join(', ') + ' (potvrď v dashboarde)');
}
return [{ json: { chatId: built.chatId, messageId: built.messageId, text: lines.join('\n').slice(0, 3900) } }];
